const GearGraphic = ({ color, size }: { color: string, size: number }) => (
  <svg width={size} height={size} viewBox="0 0 100 100" style={{ overflow: 'visible', filter: `drop-shadow(0 0 20px ${color}44)` }}>
    <circle cx="50" cy="50" r="35" fill="none" stroke={color} strokeWidth="6" />
    <circle cx="50" cy="50" r="15" fill="none" stroke={color} strokeWidth="4" />
    <circle cx="50" cy="50" r="6" fill={color} />
    {[0, 60, 120].map(angle => (
      <line key={angle} x1="50" y1="35" x2="50" y2="65" stroke={color} strokeWidth="4" transform={`rotate(${angle} 50 50)`} />
    ))}
    {[...Array(12)].map((_, i) => (
      <rect key={i} x="46" y="7" width="8" height="8" fill={color} transform={`rotate(${i * 30} 50 50)`} rx="2" />
    ))}
  </svg>
);

// --- MAIN COMPONENT ---
const FlywheelAnimation: React.FC<FlywheelAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  flywheelColor = "#aa00e6",
  iconColor = "#ffffff",
  textColor = "#ffffff",
  finalText = "Your product IS the content.",
  finalTextFontFamily = "INTER-VARIABLEFONT_OPSZ,WGHT (3)"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser safety for background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimension calculations
  const s = Math.min(width, height);
  const orbitRadius = s * 0.32;
  const iconSize = s * 0.12;
  const gearSize = s * 0.35;
  const startRadius = s * 1.5;

  // Compute smooth, monotonically accelerating rotation pure function
  let rotation = frame * 0.8;
  if (frame > 60) rotation += (frame - 60) * 1.5;
  if (frame > 120) rotation += (frame - 120) * 2.5;
  if (frame > 180) rotation += (frame - 180) * 3.5;

  // Springs for icons locking in
  const p1 = spring({ frame: frame - 40, fps, config: { damping: 14, mass: 0.8 } });
  const p2 = spring({ frame: frame - 100, fps, config: { damping: 14, mass: 0.8 } });
  const p3 = spring({ frame: frame - 160, fps, config: { damping: 14, mass: 0.8 } });

  // Interpolate radius to snap in from outside
  const r1 = interpolate(p1, [0, 1], [startRadius, orbitRadius]);
  const r2 = interpolate(p2, [0, 1], [startRadius, orbitRadius]);
  const r3 = interpolate(p3, [0, 1], [startRadius, orbitRadius]);

  // Pulse effects exactly when they lock in
  const pulse1Scale = interpolate(frame, [55, 75], [1, 1.8], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const pulse1Opacity = interpolate(frame, [55, 75], [0.8, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  
  const pulse2Scale = interpolate(frame, [115, 135], [1, 1.8], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const pulse2Opacity = interpolate(frame, [115, 135], [0.8, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  
  const pulse3Scale = interpolate(frame, [175, 195], [1, 1.8], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const pulse3Opacity = interpolate(frame, [175, 195], [0.8, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  // Final text reveal spring
  const textProgress = spring({ frame: frame - 210, fps, config: { damping: 12, mass: 0.9 } });
  const textOpacity = interpolate(textProgress, [0, 1], [0, 1]);
  const textY = interpolate(textProgress, [0, 1], [60, 0]);
  const textScale = interpolate(textProgress, [0, 1], [0.95, 1]);

  // Shared Icon Wrapper Style
  const getIconWrapperStyle = (angle: number, r: number, p: number) => ({
    position: 'absolute' as const,
    left: -iconSize / 2,
    top: -iconSize / 2,
    width: iconSize,
    height: iconSize,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    // Rotate to position, push out by radius, then counter-rotate to stay upright
    transform: `rotate(${angle}deg) translateX(${r}px) rotate(${-angle - rotation}deg) scale(${p})`,
    opacity: p,
    transition: 'none'
  });

  const getInnerCircleStyle = () => ({
    width: '100%',
    height: '100%',
    backgroundColor: bgColor, // Hides the orbit path behind it
    border: `3px solid ${flywheelColor}`,
    borderRadius: '50%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    position: 'relative' as const,
    zIndex: 2,
    boxShadow: `0 0 15px ${flywheelColor}33`
  });

  const getPulseStyle = (scale: number, opacity: number) => ({
    position: 'absolute' as const,
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    borderRadius: '50%',
    backgroundColor: flywheelColor,
    transform: `scale(${scale})`,
    opacity,
    zIndex: 1,
    transition: 'none'
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Diagram Dot Grid Background */}
      <AbsoluteFill style={{ opacity: 0.15, transition: "none" }}>
        <svg width="100%" height="100%">
          <defs>
            <pattern id="dot-grid" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
              <circle cx="2" cy="2" r="2" fill={flywheelColor} />
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#dot-grid)" />
        </svg>
      </AbsoluteFill>

      {/* Center Anchor Point for the Diagram */}
      <AbsoluteFill style={{ justifyContent: 'center', alignItems: 'center', transition: "none" }}>
        
        {/* Orbit Ring (Static dashed line) */}
        <div style={{
          position: 'absolute',
          width: orbitRadius * 2,
          height: orbitRadius * 2,
          border: `3px dashed ${flywheelColor}44`,
          borderRadius: '50%',
          transition: 'none'
        }} />

        {/* Master Rotating System */}
        <div style={{
          position: 'absolute',
          width: 0,
          height: 0,
          transform: `rotate(${rotation}deg)`,
          transition: 'none'
        }}>
          
          {/* Central Gear */}
          <div style={{
            position: 'absolute',
            left: -gearSize / 2,
            top: -gearSize / 2,
            width: gearSize,
            height: gearSize,
            transition: 'none'
          }}>
            <GearGraphic color={flywheelColor} size={gearSize} />
          </div>

          {/* Icon 1: Blog */}
          <div style={getIconWrapperStyle(0, r1, p1)}>
            <div style={getPulseStyle(pulse1Scale, pulse1Opacity)} />
            <div style={getInnerCircleStyle()}>
              <BlogIcon color={iconColor} />
            </div>
          </div>

          {/* Icon 2: Changelog */}
          <div style={getIconWrapperStyle(120, r2, p2)}>
            <div style={getPulseStyle(pulse2Scale, pulse2Opacity)} />
            <div style={getInnerCircleStyle()}>
              <ChangelogIcon color={iconColor} />
            </div>
          </div>

          {/* Icon 3: Share */}
          <div style={getIconWrapperStyle(240, r3, p3)}>
            <div style={getPulseStyle(pulse3Scale, pulse3Opacity)} />
            <div style={getInnerCircleStyle()}>
              <ShareIcon color={iconColor} />
            </div>
          </div>

        </div>
      </AbsoluteFill>

      {/* Final Build-Up Text */}
      <AbsoluteFill style={{
        justifyContent: 'flex-end',
        alignItems: 'center',
        paddingBottom: height * 0.15,
        transition: 'none'
      }}>
        <h1 style={{
          fontFamily: finalTextFontFamily,
          color: textColor,
          fontSize: s * 0.08, // Dynamically sized to width
          fontWeight: 800,
          textAlign: 'center',
          lineHeight: 1.1,
          opacity: textOpacity,
          transform: `translateY(${textY}px) scale(${textScale})`,
          maxWidth: '85%',
          margin: 0,
          textShadow: `0 4px 20px ${backgroundColor}`,
          transition: 'none'
        }}>
          {finalText}
        </h1>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default FlywheelAnimation;